const items = $input.all();

// Both responses are inside the first input item
const data = items[0].json;

// Extract image analysis
const imageDescription =
  data["0"]?.content?.[0]?.text || "";

// Extract text analysis
let textData =
  data.output?.[0]?.content?.[0]?.text || {};

// If textData is a JSON string, parse it
if (typeof textData === "string") {
  try {
    textData = JSON.parse(textData);
  } catch (e) {
    textData = {};
  }
}

return [
  {
    json: {
      image_description: imageDescription,
      ...textData
    }
  }
];

let influencer;

try {
  influencer = $('Loop Over Items3').item.json;
} catch (e) {
  influencer = $input.first().json;
}

const post = $json.items?.[0];

if (!post) {
  return [{
    json: {
      influencerId: influencer.id,
      influencerName: influencer.name,
      providerId: influencer.influncrerProviderId,
      username: influencer.username,
      accountId: influencer.connectionAccountUnipile || 'e8SNXWPnT92sUstGK-eO0g',
      hasPost: false,
      isRecentPost: false,
      skipReason: 'No latest post found'
    }
  }];
}

const unipilePostId = post.social_id || post.id;
const instagramPostId = post.id;

const postDateRaw =
  post.created_at ||
  post.parsed_datetime ||
  post.date;

let postDate = null;

if (typeof postDateRaw === 'number') {
  postDate = new Date(postDateRaw * 1000);
} else if (postDateRaw) {
  postDate = new Date(postDateRaw);
}

const postAgeHours =
  postDate && !Number.isNaN(postDate.getTime())
    ? (Date.now() - postDate.getTime()) / (1000 * 60 * 60)
    : null;

const isRecentPost = postAgeHours !== null && postAgeHours <= 48;

const alreadyCommented =
  String(influencer.lastCommentedPostId || '') ===
  String(unipilePostId);

return [{
  json: {
    influencerId: influencer.id,
    influencerName: influencer.name,

    influencerProfileUrl:
      influencer.accountUrl?.primaryLinkUrl ||
      influencer.accountUrlPrimaryLinkUrl ||
      "",

    providerId: influencer.influncrerProviderId,
    username: influencer.username,

    accountId:
      influencer.connectionAccountUnipile ||
      'e8SNXWPnT92sUstGK-eO0g',

    lastCommentedPostId:
      influencer.lastCommentedPostId,

    postId: unipilePostId,
    unipilePostId,
    instagramPostId,

    postUrl:
      post.url ||
      post.share_url ||
      "",

    postText:
      post.caption?.text ||
      post.text ||
      "",

    postDate:
      postDate
        ? postDate.toISOString()
        : null,

    postAgeHours,
    isRecentPost,

    commentCount:
      post.comment_count ??
      post.comment_counter ??
      0,

    reactionCount:
      post.like_count ??
      post.reaction_counter ??
      0,

    repostCount:
      post.repost_counter ?? 0,

    canComment:
      post.permissions?.can_post_comments ?? true,

    canReact:
      post.permissions?.can_react ?? true,

    alreadyCommented,
    hasPost: true,

    rawPost: post
  }
}];
